<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue"
import { apiRequest } from "../../api"
import AdminHeader from "../../components/AdminHeader.vue"
import TagChip from "../../components/TagChip.vue"
import { useAuthStore } from "../../stores/auth"

interface Tag { id:number; name:string; color:string|null; description:string|null }
interface Source { id:number; name:string }
interface Target { target_type:string; folder_segment:boolean }
interface Rule { id:number; library_source_id:number|null; legacy_kind:string|null; match_mode:"contains"|"regex"|"path_relation"; pattern:string|null; path_value:string|null; path_relation:"direct_child"|"self_or_descendant"|null; enabled:boolean; targets:Target[]; match_count:number }
interface Preview { model_name:string; relative_path:string }
const auth=useAuthStore(), canTags=auth.can("tags.manage"), canRules=auth.can("tag_rules.manage")&&Boolean(auth.user?.source_access.all_sources)
const tags=ref<Tag[]>([]), sources=ref<Source[]>([]), selectedId=ref<number|null>(null), rules=ref<Rule[]>([]), preview=ref<Preview[]>([]), busy=ref(false), error=ref(""), feedback=ref(""), editingRule=ref<number|null>(null), tagMode=ref<"view"|"create"|"edit">("view")
const selected=computed(()=>tags.value.find((tag)=>tag.id===selectedId.value)??null)
const textMode=computed(()=>ruleForm.match_mode!=="path_relation")
const options=[['model_relative_path','Model relative path'],['archive_filename','Archive filename'],['archive_entry_path','Archive entry path'],['archive_entry_name','Archive entry filename']] as const
const tagForm=reactive({name:"",color:"#5eead4",description:""})
const ruleForm=reactive({match_mode:"contains" as Rule["match_mode"],pattern:"",path_value:"",path_relation:"self_or_descendant",library_source_id:"",enabled:true,targets:["archive_entry_path"] as string[],folder_segment:false})
function resetTag(){Object.assign(tagForm,{name:"",color:"#5eead4",description:""})}
function resetRule(){Object.assign(ruleForm,{match_mode:"contains",pattern:"",path_value:"",path_relation:"self_or_descendant",library_source_id:"",enabled:true,targets:["archive_entry_path"],folder_segment:false});editingRule.value=null;preview.value=[]}
function selectTag(id:number){selectedId.value=id;tagMode.value="view";resetTag();resetRule();void loadRules()}
async function loadRules(){rules.value=canRules&&selectedId.value?await apiRequest<Rule[]>(`/api/admin/tags/${selectedId.value}/assignment-rules`):[]}
async function load(){tags.value=await apiRequest<Tag[]>("/api/admin/tags");if(!selected.value)selectedId.value=tags.value[0]?.id??null;if(canRules)sources.value=await apiRequest<Source[]>("/api/admin/tags/library-sources");await loadRules()}
function createTag(){resetTag();tagMode.value="create";resetRule()}
function editTag(){if(selected.value){Object.assign(tagForm,selected.value);tagMode.value="edit"}}
async function saveTag(){if(!canTags)return;busy.value=true;try{const update=tagMode.value==="edit";const tag=await apiRequest<Tag>(update?`/api/admin/tags/${selectedId.value}`:"/api/admin/tags",{method:update?"PUT":"POST",body:JSON.stringify({...tagForm,description:tagForm.description||null})});selectedId.value=tag.id;tagMode.value="view";await load();feedback.value=`Tag ${update?"updated":"created"}.`}catch(e){error.value=e instanceof Error?e.message:"Unable to save tag"}finally{busy.value=false}}
async function deleteTag(){if(!selected.value||!confirm(`Delete ${selected.value.name}?`))return;await apiRequest(`/api/admin/tags/${selected.value.id}`,{method:"DELETE"});selectedId.value=null;await load();feedback.value="Tag deleted."}
function payload(){const library_source_id=ruleForm.library_source_id?Number(ruleForm.library_source_id):null;if(ruleForm.match_mode==="path_relation")return{match_mode:"path_relation",path_value:ruleForm.path_value,path_relation:ruleForm.path_relation,library_source_id,enabled:ruleForm.enabled,targets:[{target_type:"model_relative_path",folder_segment:false}]};return{match_mode:ruleForm.match_mode,pattern:ruleForm.pattern,library_source_id,enabled:ruleForm.enabled,targets:ruleForm.targets.map((target_type)=>({target_type,folder_segment:target_type==="model_relative_path"&&ruleForm.folder_segment}))}}
async function saveRule(){if(!selectedId.value)return;busy.value=true;try{await apiRequest(editingRule.value?`/api/admin/tag-assignment-rules/${editingRule.value}`:`/api/admin/tags/${selectedId.value}/assignment-rules`,{method:editingRule.value?"PUT":"POST",body:JSON.stringify(payload())});resetRule();await loadRules();feedback.value="Assignment rule saved."}catch(e){error.value=e instanceof Error?e.message:"Unable to save assignment rule"}finally{busy.value=false}}
async function previewRule(){busy.value=true;try{preview.value=await apiRequest<Preview[]>("/api/admin/tag-assignment-rules/preview",{method:"POST",body:JSON.stringify({...payload(),limit:25})})}catch(e){error.value=e instanceof Error?e.message:"Unable to preview rule"}finally{busy.value=false}}
function editRule(rule:Rule){editingRule.value=rule.id;Object.assign(ruleForm,{match_mode:rule.match_mode,pattern:rule.pattern??"",path_value:rule.path_value??"",path_relation:rule.path_relation??"self_or_descendant",library_source_id:rule.library_source_id?String(rule.library_source_id):"",enabled:rule.enabled,targets:rule.targets.map((target)=>target.target_type),folder_segment:rule.targets.some((target)=>target.target_type==="model_relative_path"&&target.folder_segment)})}
async function removeRule(rule:Rule){if(!confirm("Delete this assignment rule?"))return;await apiRequest(`/api/admin/tag-assignment-rules/${rule.id}`,{method:"DELETE"});await loadRules();feedback.value="Assignment rule deleted."}
async function reevaluate(rule:Rule){busy.value=true;try{await apiRequest(`/api/admin/tag-assignment-rules/${rule.id}/re-evaluate`,{method:"POST"});await loadRules();feedback.value="Assignment rule re-evaluated."}finally{busy.value=false}}
function mode(rule:Rule){return rule.match_mode==="path_relation"?"Folder path":rule.match_mode==="regex"?"Regular expression":"Text contains"}
function targetNames(rule:Rule){return rule.targets.map((target)=>options.find(([value])=>value===target.target_type)?.[1]??target.target_type).join(", ")}
watch(()=>ruleForm.match_mode,()=>{if(ruleForm.match_mode==="path_relation")ruleForm.targets=["model_relative_path"]});onMounted(load)
</script>

<template><main class="admin-shell"><AdminHeader title="Tags"/><p v-if="error" class="form-error">{{error}}</p><p v-if="feedback" class="success-panel">{{feedback}}</p><section class="tags-layout"><aside class="panel"><header class="heading"><div><h2>Tags</h2><p class="panel-copy">Select a tag to manage it.</p></div><button v-if="canTags" class="primary-button" @click="createTag">Create tag</button></header><div class="tag-list"><button v-for="tag in tags" :key="tag.id" class="tag-select" :class="{selected:tag.id===selectedId}" :aria-pressed="tag.id===selectedId" @click="selectTag(tag.id)"><TagChip :color="tag.color" :description="tag.description">{{tag.name}}</TagChip></button><p v-if="!tags.length" class="panel-copy">No tags yet.</p></div></aside><section class="content"><section v-if="tagMode!=='view'" class="panel"><h2>{{tagMode==='create'?'Create tag':'Edit tag'}}</h2><form class="form-grid" @submit.prevent="saveTag"><label><span>Name</span><input v-model="tagForm.name" required maxlength="80"></label><label><span>Colour</span><input v-model="tagForm.color" type="color"></label><label class="wide"><span>Description</span><textarea v-model="tagForm.description" maxlength="1000"></textarea></label><div class="actions wide"><button class="primary-button" :disabled="busy">{{tagMode==='create'?'Create tag':'Save changes'}}</button><button type="button" class="secondary-button" @click="tagMode='view';resetTag()">Cancel</button></div></form></section><template v-else-if="selected"><section class="panel"><header class="heading"><div><h2>{{selected.name}}</h2><p class="panel-copy">{{selected.description||'Manage this tag and its assignment rules.'}}</p></div><div v-if="canTags" class="actions"><button class="secondary-button" @click="editTag">Edit tag</button><button class="danger-button" @click="deleteTag">Delete tag</button></div></header></section><section v-if="canRules" class="panel"><header class="heading"><div><h2>Assignment rules</h2><p class="panel-copy">A rule assigns this tag when one selected target matches.</p></div></header><form class="rule-form" @submit.prevent="saveRule"><fieldset><legend>{{editingRule?'Edit assignment rule':'Add assignment rule'}}</legend><div class="form-grid"><label><span>Match mode</span><select v-model="ruleForm.match_mode"><option value="contains">Text contains</option><option value="regex">Regular expression</option><option value="path_relation">Folder path</option></select></label><label><span>Source scope</span><select v-model="ruleForm.library_source_id"><option value="">All sources</option><option v-for="source in sources" :key="source.id" :value="String(source.id)">{{source.name}}</option></select></label><label v-if="textMode" class="wide"><span>{{ruleForm.match_mode==='regex'?'Regular expression':'Text to match'}}</span><input v-model="ruleForm.pattern" required :placeholder="ruleForm.match_mode==='regex'?'(_P|P\\.)[2-9]':'Search text'"></label><label v-else class="wide"><span>Folder path</span><input v-model="ruleForm.path_value" required></label><label v-if="!textMode"><span>Include</span><select v-model="ruleForm.path_relation"><option value="self_or_descendant">Folder and subfolders</option><option value="direct_child">Direct children only</option></select></label><fieldset v-if="textMode" class="wide targets"><legend>Search targets</legend><label v-for="[target,label] in options" :key="target"><input v-model="ruleForm.targets" type="checkbox" :value="target"> {{label}}</label><label v-if="ruleForm.targets.includes('model_relative_path')"><input v-model="ruleForm.folder_segment" type="checkbox"> Match individual folder names</label></fieldset><label class="enabled"><input v-model="ruleForm.enabled" type="checkbox"> Enabled</label><div class="actions wide"><button class="primary-button" :disabled="busy">{{editingRule?'Save rule':'Add rule'}}</button><button v-if="textMode" type="button" class="secondary-button" @click="previewRule">Preview</button><button v-if="editingRule" type="button" class="secondary-button" @click="resetRule">Cancel</button></div></div></fieldset></form><div v-if="preview.length" class="preview"><strong>Preview matches</strong><ul><li v-for="model in preview" :key="model.relative_path">{{model.model_name}} · {{model.relative_path}}</li></ul></div><div class="rule-list"><article v-for="rule in rules" :key="rule.id" class="rule-row"><div><div class="badges"><span class="badge">{{mode(rule)}}</span><span v-if="rule.legacy_kind" class="badge legacy">Migrated</span><span class="badge" :class="{disabled:!rule.enabled}">{{rule.enabled?'Active':'Disabled'}}</span><span class="badge">{{rule.match_count}} matches</span></div><p>{{targetNames(rule)}}</p><small>{{rule.library_source_id?'Source scoped':'All sources'}}</small></div><div class="actions"><button class="secondary-button" @click="editRule(rule)">Edit</button><button class="secondary-button" @click="reevaluate(rule)">Re-evaluate</button><button class="danger-button" @click="removeRule(rule)">Delete</button></div></article><p v-if="!rules.length" class="panel-copy">No assignment rules for this tag.</p></div></section><section v-else class="panel"><h2>Assignment rules</h2><p class="panel-copy">Assignment rules are unavailable for this account.</p></section></template><section v-else class="panel"><h2>Choose a tag</h2><p class="panel-copy">Select a tag from the list.</p></section></section></section></main></template>

<style scoped>.tags-layout{display:grid;grid-template-columns:minmax(15rem,.75fr) minmax(0,2fr);gap:1rem;align-items:start}.content{display:grid;gap:1rem}.heading{display:flex;justify-content:space-between;gap:1rem;align-items:start}.heading h2{margin:0}.tag-list{display:grid;gap:.4rem;margin-top:1rem}.tag-select{display:block;box-sizing:border-box;width:100%;text-align:left;padding:.65rem .75rem;border:2px solid transparent;border-radius:.45rem;background:var(--panel-background);transition:background-color .15s ease,border-color .15s ease,box-shadow .15s ease}.tag-select:hover{background:var(--muted-background);border-color:var(--accent-color)}.tag-select:focus-visible{outline:3px solid var(--accent-color);outline-offset:2px}.tag-select.selected{border-color:var(--accent-color);background:var(--muted-background);box-shadow:inset .25rem 0 var(--accent-color)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.85rem}.form-grid label{display:grid;gap:.3rem}.wide{grid-column:1/-1}.actions{display:flex;gap:.55rem;flex-wrap:wrap;align-items:center}.rule-form{margin:1rem 0}.rule-form fieldset{border:1px solid var(--border-color);border-radius:.5rem;padding:1rem}.rule-form legend{padding:0 .35rem;font-weight:600}.targets{display:flex!important;gap:.6rem 1rem;flex-wrap:wrap}.targets label,.enabled{display:flex!important;align-items:center;gap:.45rem}.preview{margin:.75rem 0;padding:.75rem 1rem;border-radius:.45rem;background:var(--muted-background)}.preview ul{margin:.45rem 0 0;padding-left:1.25rem}.rule-list{display:grid;gap:.65rem}.rule-row{display:flex;justify-content:space-between;gap:1rem;padding:.85rem 1rem;border:1px solid var(--border-color);border-radius:.55rem;background:var(--panel-background)}.rule-row p{margin:.45rem 0 .2rem}.badges{display:flex;gap:.35rem;flex-wrap:wrap}.badge{padding:.15rem .45rem;border-radius:999px;background:var(--muted-background);font-size:.8rem}.badge.legacy{background:#e9d5ff}.badge.disabled{opacity:.65}@media(max-width:800px){.tags-layout,.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.rule-row,.heading{display:grid}}</style>
